INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass der Netzwerkprotokollstapel immer nur aus vier Schichten besteht. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Anzahl variiert (z. B. OSI 7)"}, {"text": "Ja", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich einen Netzwerkprotokollstapel für ein IT-System analysiere?', 3, '[{"text": "Schichtenfunktion", "correct": true, "because": "Definiert Aufgaben"}, {"text": "Schnellste Implementierung", "correct": false, "because": "Struktur zählt"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schichten gehören zum TCP/IP-Protokollstapel?', 5, '[{"text": "Netzwerkschicht", "correct": true, "because": "IP-Adressierung"}, {"text": "Transportschicht", "correct": true, "because": "TCP/UDP"}, {"text": "Büroschicht", "correct": false, "because": "Kein Bestandteil"}, {"text": "Farbschicht", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Der Netzwerkprotokollstapel ermöglicht Kommunikation. b) Alle Schichten sind immer physisch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Logische Schichten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich einen Netzwerkprotokollstapel für ein IT-System analysiere?', 4, '[{"text": "Schichtenaufbau", "correct": false, "because": "Definiert Funktion"}, {"text": "Protokolle", "correct": false, "because": "Ermöglichen Kommunikation"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Netzwerkfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob der Netzwerkprotokollstapel nur für TCP/IP gilt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch OSI, andere Modelle"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Netzwerkprotokollstapel?', 3, '[{"text": "Strukturierte Kommunikation", "correct": true, "because": "Schichten organisieren"}, {"text": "Schnellste Einrichtung", "correct": false, "because": "Funktion zählt"}, {"text": "Weniger Schichten", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Protokolle sind im TCP/IP-Stapel enthalten?', 5, '[{"text": "IP", "correct": true, "because": "Netzwerkschicht"}, {"text": "TCP", "correct": true, "because": "Transportschicht"}, {"text": "Büroprotokoll", "correct": false, "because": "Kein Protokoll"}, {"text": "Farbprotokoll", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Der Netzwerkprotokollstapel hat eine Schicht für Anwendungen. b) Er ist immer hardwareabhängig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Logische Struktur"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um einen Netzwerkprotokollstapel zu implementieren?', 4, '[{"text": "Schichtenmodell", "correct": false, "because": "Definiert Struktur"}, {"text": "Protokolle", "correct": false, "because": "Ermöglichen Kommunikation"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Netzwerkfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist der Netzwerkprotokollstapel immer auf TCP/IP beschränkt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch OSI, andere Modelle"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Netzwerkprotokollstapel?', 4, '[{"text": "Modularität", "correct": true, "because": "Schichten trennen Funktionen"}, {"text": "Interoperabilität", "correct": true, "because": "Fördert Kompatibilität"}, {"text": "Schnellere Projekte", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass der Netzwerkprotokollstapel nur für große Netzwerke geeignet ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Netzwerke"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um einen Netzwerkprotokollstapel zu analysieren?', 3, '[{"text": "Schichtenaufbau", "correct": true, "because": "Definiert Funktion"}, {"text": "Günstigste Lösung", "correct": false, "because": "Struktur wichtiger"}, {"text": "Bunte Diagramme", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Der OSI-Stapel hat 7 Schichten. b) TCP/IP hat nur 2 Schichten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "TCP/IP hat 4 Schichten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei einem Netzwerkprotokollstapel?', 5, '[{"text": "Schichtenfunktion", "correct": true, "because": "Definiert Aufgaben"}, {"text": "Protokollinteraktion", "correct": true, "because": "Sichert Kommunikation"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich einen Netzwerkprotokollstapel implementiere?', 3, '[{"text": "Schichtenmodell", "correct": false, "because": "Definiert Struktur"}, {"text": "Protokolle", "correct": false, "because": "Ermöglichen Kommunikation"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Netzwerkfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Hat der TCP/IP-Stapel eine physische Schicht?', 3, '[{"text": "Nein", "correct": true, "because": "Beginnt bei Netzwerkschicht"}, {"text": "Ja", "correct": false, "because": "Falsche Annahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob der Netzwerkprotokollstapel nur für drahtlose Netzwerke gilt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kabelgebunden"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend für einen Netzwerkprotokollstapel?', 4, '[{"text": "Schichtenarchitektur", "correct": true, "because": "Organisiert Kommunikation"}, {"text": "Schnellste Einrichtung", "correct": false, "because": "Struktur zählt"}, {"text": "Bürogestaltung", "correct": false, "because": "Irrelevant"}]');
